#!/usr/bin/env node
/**
 * Convert v1 training data (plain text replies) into v2 format
 * (JSON {"sentences": [...]}) with the real system prompt from chat.js.
 * Also merges any existing v2 data.
 */

import { simulate } from "../sim/engine.js";
import { checkSentence, placeholderKeys } from "../voice/chat.js";
import { readFileSync, writeFileSync, existsSync } from "fs";

const V1_PATH = "words/training-data.jsonl";
const V2_PATH = "words/training-data-v2.jsonl";
const OUT_PATH = "words/training-data-merged.jsonl";

function buildSystemPrompt(name, keys) {
  return `You are ${name} at age 70, talking warmly to your younger self, who is sitting across from you in a mirror. You are the same person, just older. Speak in first person, naturally, in 1 to 3 short sentences, as in a relaxed conversation.

Rules, no exceptions:
- Answer what they actually asked. Feelings, memories, wisdom and small colour ("I still walk every morning") are welcome.
- NEVER write any digit and NEVER write a number as a word (no "two", "twenty", "hundred", no years, no ages, no amounts). "one" is fine in phrases like "one thing".
- Any fact about money, savings, income, health, life expectancy or age MUST be one of these placeholders, written exactly with braces: ${keys.map(k => `{${k}}`).join(", ")}. Never write a placeholder not on that list. Use a placeholder only when it fits the question.
- If asked about family, jobs, houses, or other facts you have no placeholder for, answer in feelings and values without claiming specifics.
- Never say when or how they will die. Be warm, never scary or guilt-tripping. Talk about options and choices, not fear.
- Reply as JSON only: {"sentences": ["...", "..."]}`;
}

function splitIntoSentences(text) {
  return text.split(/(?<=[.!?])\s+/).filter(s => s.trim().length > 0);
}

const results = [];

// Convert v1
const v1Lines = readFileSync(V1_PATH, "utf8").trim().split("\n");
let v1Valid = 0, v1Skipped = 0;

for (const line of v1Lines) {
  const ex = JSON.parse(line);
  if (!ex.valid) continue;

  // Simulate to get facts for this profile shape
  const profile = {
    name: ex.profile.name, age: ex.profile.age,
    sex: ex.profile.sex, province: "ON",
    income_per_year: 50000,
    savings: { tfsa: 5000, rrsp: 0, other: 0 },
    saving_per_month: 100, retirement_age: 65,
    habits: { exercise_per_week: 3, sleep_hours: 7, smoker: false, drinks_per_week: 2 },
  };
  const facts = simulate(profile);
  const keys = placeholderKeys(facts);
  const systemPrompt = buildSystemPrompt(ex.profile.name, keys);

  // Split reply into sentences and filter
  const sentences = splitIntoSentences(ex.reply);
  const clean = sentences.filter(s => checkSentence(s, facts));

  if (clean.length === 0) { v1Skipped++; continue; }

  // Keep at most 3 sentences
  const kept = clean.slice(0, 3);
  const replyJson = JSON.stringify({ sentences: kept });

  results.push({
    profile: { name: ex.profile.name, age: ex.profile.age, sex: ex.profile.sex },
    question: ex.question,
    reply: replyJson,
    valid: true,
    reason: null,
    system_prompt: systemPrompt,
    user_message: ex.question,
    source: "v1-converted",
  });
  v1Valid++;
}

console.log(`v1: ${v1Valid} converted, ${v1Skipped} skipped`);

// Add any v2 data if it exists
if (existsSync(V2_PATH)) {
  const v2Lines = readFileSync(V2_PATH, "utf8").trim().split("\n");
  let v2Count = 0;
  for (const line of v2Lines) {
    if (!line.trim()) continue;
    const ex = JSON.parse(line);
    if (ex.valid) {
      ex.source = "v2-generated";
      results.push(ex);
      v2Count++;
    }
  }
  console.log(`v2: ${v2Count} added`);
}

// Shuffle
for (let i = results.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [results[i], results[j]] = [results[j], results[i]];
}

writeFileSync(OUT_PATH, results.map(r => JSON.stringify(r)).join("\n") + "\n");
console.log(`Total: ${results.length} examples written to ${OUT_PATH}`);

