212	  { slider: "exercise_per_week", nudge: (input) => ({ ...input, habits: { ...input.habits, exercise_per_week: Math.min(input.habits.exercise_per_week + 2, 7) } }), label: () => "exercising twice more a week" },
213	  { slider: "sleep_hours", nudge: (input) => ({ ...input, habits: { ...input.habits, sleep_hours: 7.5 } }), label: () => "getting seven to eight hours of sleep" },
214	  { slider: "smoker", nudge: (input) => ({ ...input, habits: { ...input.habits, smoker: false } }), label: () => "quitting smoking" },
215	];
216	
217	function rankBestChange(input, baseFacts) {
218	  let best = null;
219	  let bestScore = 0;
220	
221	  for (const { slider, nudge, label } of SLIDER_NUDGES) {
222	    const nudged = nudge(input);
223	    if (JSON.stringify(nudged) === JSON.stringify(input)) continue;
