let current = "s-hero";
function show(id) {
  const old = $(current);
  const next = $(id);
  if (old === next) return;
  old.classList.add("leaving");
  setTimeout(() => {
    old.classList.remove("on", "leaving");
    next.classList.add("on");
    current = id;
  }, 300);
}

