423	// ---- Upload: voice clone + field extraction in parallel ----
424	let reading = null, voiceOk = true, voiceProblem = "";
425	async function upload() {
426	  show("s-work");
427	  say("e-work", "");
428	  $("retry").hidden = true;
429	  const blob = new Blob(chunks, { type: recorder.mimeType || "audio/webm" });
430	  const post = url => fetch(url, { method: "POST", headers: { "content-type": blob.type }, body: blob });
431	  let cloneRes, readRes;
432	  try {
433	    [cloneRes, readRes] = await Promise.all([
434	      post("/api/voice/clone?name=" + encodeURIComponent(name)),
435	      post("/api/interview/extract"),
436	    ]);
437	  } catch {
438	    return failed("Could not reach the server. Check your connection and record again.");
439	  }
440	  const c = await cloneRes.json().catch(() => ({}));
441	  reading = await readRes.json().catch(() => ({}));
442	  if (!readRes.ok) return failed("Could not read your answers: " + (reading.error || readRes.status));
443	  voiceOk = cloneRes.ok;
444	  voiceProblem = cloneRes.ok ? "" : "Your voice could not be copied (" + (c.error || cloneRes.status) + "), so Uncle will use a stock voice.";
445	  showConfirm(reading);
446	}
