// ---- Evolution sketch drawing ----
const FIGURES = [
  { vw: 50, vh: 50, paths: [
    'M25 12 C34 7 40 16 37 25 C34 35 22 38 15 32 C8 26 10 14 18 10 C21 9 23 10 25 12',
    'M23 20 C27 18 29 22 26 25 C24 27 21 25 23 20',
  ]},
  { vw: 70, vh: 40, paths: [
    'M8 20 Q18 8 38 12 Q48 8 58 16 Q48 28 38 24 Q18 32 8 20',
    'M58 16 L66 10 M58 20 L66 26',
    'M24 17 C25 15 27 17 25 18',
  ]},
  { vw: 80, vh: 50, paths: [
    'M12 22 Q30 14 55 18 Q62 14 68 20 Q64 24 58 22',
    'M55 18 Q52 20 55 22',
    'M20 22 L17 38', 'M28 20 L25 36',
    'M45 20 L42 36', 'M52 20 L49 36',
    'M12 22 Q6 18 4 22',
  ]},
  { vw: 70, vh: 65, paths: [
    'M18 22 Q30 10 50 16 Q58 12 62 18 Q58 24 52 22',
    'M50 16 Q48 18 50 22',
    'M24 26 L20 48 L24 50', 'M32 24 L28 46 L32 48',
    'M44 22 L40 44 L44 46', 'M50 22 L46 42 L50 44',
    'M18 22 Q12 18 10 22 Q12 20 14 24',
  ]},
  { vw: 55, vh: 80, paths: [
    'M32 10 Q38 6 38 14 Q38 20 32 18 Q28 16 32 10',
    'M34 20 Q30 28 26 36 Q24 44 26 55',
    'M30 28 Q22 34 18 44', 'M28 32 L36 40',
    'M26 55 L30 72 L26 74', 'M24 54 L20 70 L16 72',
  ]},
  { vw: 50, vh: 85, paths: [
    'M26 8 Q32 4 32 12 Q32 18 26 16 Q22 14 26 8',
    'M28 18 Q28 28 27 36 Q26 44 27 54',
    'M27 26 Q20 32 18 40', 'M27 28 Q34 34 36 42',
    'M27 54 L24 72 L20 76', 'M27 54 L30 72 L34 76',
  ]},
  { vw: 45, vh: 90, paths: [
    'M22 8 Q28 3 28 10 Q28 16 22 14 Q18 12 22 8',
    'M24 16 L24 32 L24 50',
    'M24 24 L16 36', 'M24 24 L32 36',
    'M24 50 L20 70 L16 74', 'M24 50 L28 70 L32 74',
  ]},
];

function spawnSketch() {
  const fig = FIGURES[Math.random() * FIGURES.length | 0];
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  const scale = 1.2 + Math.random() * 0.6;
  svg.setAttribute('viewBox', `0 0 ${fig.vw} ${fig.vh}`);
  svg.style.cssText = `position:fixed;pointer-events:none;z-index:-1;width:${fig.vw*scale}px;height:${fig.vh*scale}px;overflow:visible;`;
  svg.style.left = (Math.random() * 70 + 10) + 'vw';
  svg.style.top = (Math.random() * 60 + 10) + 'vh';

  const pathEls = [];
  for (const d of fig.paths) {
    const p = document.createElementNS(ns, 'path');
    p.setAttribute('d', d);
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', '#0c0a09');
    p.setAttribute('stroke-width', '1.5');
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
    svg.appendChild(p);
    pathEls.push(p);
  }

  document.body.appendChild(svg);

  const lens = pathEls.map(p => { const l = p.getTotalLength(); p.style.strokeDasharray = l; p.style.strokeDashoffset = l; return l; });
  const dx = (Math.random() - 0.5) * 50, dy = -15 - Math.random() * 25;
  const dur = 7000 + Math.random() * 3000;
  const t0 = performance.now();

  (function tick(now) {
    const t = (now - t0) / dur;
    if (t >= 1) { svg.remove(); return; }
    const draw = Math.min(t / 0.35, 1);
    for (let i = 0; i < pathEls.length; i++) pathEls[i].style.strokeDashoffset = lens[i] * (1 - draw);
    let op;
    if (t < 0.12) op = (t / 0.12) * 0.22;
    else if (t < 0.55) op = 0.22;
    else op = 0.22 * (1 - (t - 0.55) / 0.45);
    svg.style.opacity = op;
    svg.style.transform = `translate(${dx * t}px,${dy * t}px)`;
    requestAnimationFrame(tick);
  })(performance.now());
}

setInterval(spawnSketch, 5000);
setTimeout(spawnSketch, 2000);

