const evoActive = [];
function spawnSketch() {
  const fig = FIGURES[Math.random() * FIGURES.length | 0];
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  const scale = 2.2 + Math.random() * 1.0;
  const w = fig.vw * scale, h = fig.vh * scale;
  svg.setAttribute('viewBox', `0 0 ${fig.vw} ${fig.vh}`);
  svg.style.cssText = `position:fixed;pointer-events:none;z-index:-1;width:${w}px;height:${h}px;overflow:visible;`;

  let x, y, ok = false;
  for (let tries = 0; tries < 15; tries++) {
    x = Math.random() * (innerWidth - w - 40) + 20;
    y = Math.random() * (innerHeight - h - 40) + 20;
    if (!evoActive.some(a => Math.abs(x - a.x) < (w + a.w) * 0.55 && Math.abs(y - a.y) < (h + a.h) * 0.55)) { ok = true; break; }
  }
  if (!ok) return;
  svg.style.left = x + 'px';
  svg.style.top = y + 'px';
  const rec = { x, y, w, h };
  evoActive.push(rec);

  const pathEls = [];
  for (const d of fig.paths) {
    const p = document.createElementNS(ns, 'path');
    p.setAttribute('d', d);
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', '#0c0a09');
    p.setAttribute('stroke-width', '1.8');
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
    svg.appendChild(p);
    pathEls.push(p);
  }

  document.body.appendChild(svg);

  const lens = pathEls.map(p => { const l = p.getTotalLength(); p.style.strokeDasharray = l; p.style.strokeDashoffset = l; return l; });
  const n = pathEls.length;
  const dx = (Math.random() - 0.5) * 40, dy = -10 - Math.random() * 20;
  const dur = 6000 + Math.random() * 2000;
  const t0 = performance.now();

  (function tick(now) {
    const t = (now - t0) / dur;
    if (t >= 1) { svg.remove(); evoActive.splice(evoActive.indexOf(rec), 1); return; }
    for (let i = 0; i < n; i++) {
      const start = (i / n) * 0.1;
      const draw = Math.max(0, Math.min((t - start) / 0.15, 1));
      pathEls[i].style.strokeDashoffset = lens[i] * (1 - draw);
    }
    let op;
    if (t < 0.08) op = (t / 0.08) * 0.25;
    else if (t < 0.55) op = 0.25;
    else op = 0.25 * (1 - (t - 0.55) / 0.45);
    svg.style.opacity = op;
    svg.style.transform = `translate(${dx * t}px,${dy * t}px)`;
    requestAnimationFrame(tick);
  })(performance.now());
}

