1	// Decide whether a reply topic deserves a floating chart, and build the chart data.
2	// Called after each reply; returns null or a chart message matching CONTRACTS.md:
3	// { kind: "line"|"bar"|"range", title, labels, datasets }
4	import { simulate } from "../sim/engine.js";
5	
6	const TOPIC_SAVINGS = /money|save|saving|savings|rich|broke|retire|enough|afford|house|home|buy/i;
7	const TOPIC_HEALTH = /health|healthy|live|long|old|age|exercise|sleep|die|life expectancy/i;
8	const TOPIC_CHANGE = /change|start|should|advice|do now|next|difference|worth|quit/i;
9	
10	// A quick deterministic projection of savings year by year (no randomness, median returns).
11	function savingsPath(profile, facts) {
12	  const age = profile.age || 20;
13	  const saving = (profile.saving_per_month || 0) * 12;
14	  const retireAge = profile.retirement_age || 65;
15	  let savings = (profile.savings?.tfsa || 0) + (profile.savings?.rrsp || 0) + (profile.savings?.other || 0);
16	  const realReturn = 0.04; // conservative median real return
17	  const labels = [];
18	  const data = [];
19	  for (let y = age; y <= 80; y += 5) {
20	    for (let a = (labels.length === 0 ? age : labels[labels.length - 1] + 1); a <= y; a++) {
21	      if (a < retireAge) {
22	        savings = savings * (1 + realReturn) + saving;
23	      } else {
24	        const withdraw = Math.max(0, (profile.income_per_year || 55000) * 0.7 * 0.5);
25	        savings = Math.max(0, savings * (1 + realReturn) - withdraw);
26	      }
27	    }
28	    labels.push(String(y));
29	    data.push(Math.round(savings));
30	  }
31	  return { labels, data };
32	}
33	
34	export function chartForReply(question, profile, facts) {
35	  if (!facts || !profile) return null;
36	
37	  if (TOPIC_SAVINGS.test(question)) {
38	    const path = savingsPath(profile, facts);
39	    return {
40	      kind: "line",
41	      title: "Your savings over time",
42	      labels: path.labels,
43	      datasets: [
44	        { label: "Projected savings", data: path.data },
45	      ],
46	    };
47	  }
48	
49	  if (TOPIC_HEALTH.test(question)) {
50	    return {
51	      kind: "range",
52	      title: "Life expectancy range",
53	      labels: ["Life expectancy", "Healthy years"],
54	      datasets: [
55	        { label: "Low (10th %ile)", data: [facts.life_expectancy.low, facts.healthy_years.low] },
56	        { label: "Median", data: [facts.life_expectancy.median, facts.healthy_years.median] },
57	        { label: "High (90th %ile)", data: [facts.life_expectancy.high, facts.healthy_years.high] },
58	      ],
59	    };
