202	  // Waits for the head build; resolves to the saved head record, or null.
203	  async function waitForHead(onStage) {
204	    for (let i = 0; i < 240 && job; i++) {
205	      try {
206	        const r = await fetch("/api/head-jobs/" + encodeURIComponent(job.id), { headers: { authorization: "Bearer " + teamKey } });
