343	  // ---- "Did we get this right?" ----
344	  const ROWS = [
345	    ["age", "Age", "number"], ["sex", "Sex", "select:male,female"], ["province", "Province (2 letters)", "text"],
346	    ["income_per_year", "Income per year ($)", "number"], ["savings.tfsa", "TFSA savings ($)", "number"],
