// ---- Tap questions (Jeffrey's interview flow) ----
const PNS = ["Prefer not to say", null];
const qNum = (path, list) => list.map(([label, v]) => [label, { [path]: v }]);
const QUESTIONS = [
  { text: "How old are you?", type: "age" },
  { text: "Which fits you best?", note: "Used for the health averages and to match your voice.", opts: [["Male", { sex: "male" }], ["Female", { sex: "female" }], ["Prefer not to say", { sex: null }]] },
  { text: "Roughly what do you earn in a year, before tax?", opts: [...qNum("income_per_year", [["Under $20,000", 15000], ["$20,000 to $40,000", 30000], ["$40,000 to $70,000", 55000], ["$70,000 to $100,000", 85000], ["Over $100,000", 120000]]), ["Prefer not to say", { income_per_year: null }]] },
  { text: "How much do you have saved in total right now?", note: "All accounts together, rough is fine.", opts: [...[["Nothing yet", 0], ["Under $1,000", 500], ["$1,000 to $5,000", 3000], ["$5,000 to $20,000", 12000], ["Over $20,000", 30000]].map(([l, v]) => [l, { "savings.tfsa": null, "savings.rrsp": null, "savings.other": v }]), ["Prefer not to say", { "savings.tfsa": null, "savings.rrsp": null, "savings.other": null }]] },
  { text: "How much do you put away each month?", opts: [...qNum("saving_per_month", [["Nothing right now", 0], ["Under $50", 25], ["$50 to $150", 100], ["$150 to $300", 225], ["Over $300", 400]]), ["Prefer not to say", { saving_per_month: null }]] },
  { text: "At what age would you like to stop working?", opts: [...qNum("retirement_age", [["Around 55", 55], ["Around 60", 60], ["Around 65", 65], ["Around 70", 70]]), ["Not sure", { retirement_age: null }]] },
  { text: "How many times a week do you exercise?", note: "Anything that gets your heart rate up counts.", opts: [...qNum("habits.exercise_per_week", [["Never", 0], ["1 to 2 times", 2], ["3 to 4 times", 4], ["5 or more", 6]]), ["Prefer not to say", { "habits.exercise_per_week": null }]] },
  { text: "How much do you usually sleep a night?", opts: [...qNum("habits.sleep_hours", [["Under 6 hours", 5], ["6 to 7 hours", 6.5], ["7 to 8 hours", 7.5], ["9 hours or more", 9]]), ["Prefer not to say", { "habits.sleep_hours": null }]] },
  { text: "Do you smoke or vape?", note: "We ask so your numbers are realistic, not to judge.", opts: [["No", { "habits.smoker": false }], ["Yes, sometimes or regularly", { "habits.smoker": true }], ["Prefer not to say", { "habits.smoker": null }]] },
  { text: "How many alcoholic drinks do you have in a typical week?", note: "Same deal: no judgment, just realistic numbers.", opts: [...qNum("habits.drinks_per_week", [["None", 0], ["1 to 3", 2], ["4 to 7", 6], ["8 to 14", 11], ["15 or more", 18]]), ["Prefer not to say", { "habits.drinks_per_week": null }]] },
];
const picked = {};
let qi = 0;
function goAsk() { qi = 0; show("s-ask"); renderQ(); }
function renderQ() {
  const q = QUESTIONS[qi];
  $("q-count").textContent = "Question " + (qi + 1) + " of " + QUESTIONS.length;
  $("q-fill").style.width = Math.round((100 * qi) / QUESTIONS.length) + "%";
  $("q-text").textContent = q.text;
  $("q-note").textContent = q.note || "";
  $("q-opts").replaceChildren();
  $("q-num-wrap").hidden = q.type !== "age";
  say("e-ask", "");
  const done = picked[qi];
  $("q-next").disabled = !done;
  $("q-next").textContent = qi === QUESTIONS.length - 1 ? "Done" : "Next";
  $("q-back").hidden = qi === 0;
  if (q.type === "age") {
    $("q-num").value = done ? done.age : "";
    $("q-opts").hidden = true;
    return;
  }
  $("q-opts").hidden = false;
  q.opts.forEach(([label, set], i) => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = label;
    b.setAttribute("aria-pressed", done && done.__i === i ? "true" : "false");
    b.onclick = () => { picked[qi] = { ...set, __i: i }; renderQ(); };
    $("q-opts").append(b);
  });
}
$("q-num").oninput = () => {
  const v = Number($("q-num").value);
  const ok = Number.isInteger(v) && v >= 13 && v <= 100;
  picked[0] = ok ? { age: v } : undefined;
  $("q-next").disabled = !ok;
  say("e-ask", $("q-num").value && !ok ? "Enter a whole number between 13 and 100." : "");
