1	// Interview -> simulation fields (PLAN.md Part 1, "Getting inputs from the interview").
2	// Gemini reads the interview (as audio or as a transcript) with structured output and fills in
3	// ONLY what the person actually said. Anything not mentioned stays null; our code, not the
4	// model, applies the documented defaults and flags them, so the confirm screen can show
5	// "assumed" values honestly. Output shape = CONTRACTS.md "Interview fields".
6	
7	const API = "https://generativelanguage.googleapis.com/v1beta/models";
8	export const DEFAULT_MODEL = "gemini-3.5-flash-lite"; // same answers as 3.5-flash in our check, about 5x faster
9	
10	const SYSTEM = `You fill in a form from a short interview with a young Canadian about their money and health habits.
11	Rules:
12	- Use ONLY what the person clearly said. If something was not said, return null. Never guess, estimate or assume.
13	- Never infer sex from the person's name or voice. Only fill "sex" if they say it themselves.
14	- Convert to the units asked: income_per_year in dollars per YEAR, saving_per_month in dollars per MONTH. Do the arithmetic only when the person gave the numbers (for example "$1200 a year" is 100 a month). If you would have to guess hours or weeks, return null.
15	- saving_per_month is money the person puts aside each month (or each year, divided by 12). It is NOT a balance: never copy it into tfsa, rrsp or other_savings. Those three are only what they say they ALREADY HAVE saved. If they say they have nothing saved, other_savings is 0.
16	- "30k" is 30000. Savings amounts are dollars now, split by account (tfsa, rrsp, other_savings) only if they said which; money with no account named goes in other_savings.
17	- province is the two-letter Canadian code (ON, BC, QC...). exercise_per_week is workouts per week. sleep_hours is hours per night. drinks_per_week is alcoholic drinks per week. smoker is true only if they smoke or vape nicotine now.
18	- "transcript" is a clean word-for-word transcript of what was said.`;
19	
20	const nullable = (type, extra = {}) => ({ type, nullable: true, ...extra });
21	const SCHEMA = {
22	  type: "OBJECT",
23	  properties: {
24	    transcript: { type: "STRING" },
25	    name: nullable("STRING"),
26	    age: nullable("INTEGER"),
27	    sex: nullable("STRING", { enum: ["male", "female"] }),
28	    province: nullable("STRING"),
29	    income_per_year: nullable("NUMBER"),
30	    tfsa: nullable("NUMBER"),
31	    rrsp: nullable("NUMBER"),
32	    other_savings: nullable("NUMBER"),
33	    saving_per_month: nullable("NUMBER"),
34	    retirement_age: nullable("INTEGER"),
35	    exercise_per_week: nullable("NUMBER"),
36	    sleep_hours: nullable("NUMBER"),
37	    smoker: nullable("BOOLEAN"),
38	    drinks_per_week: nullable("NUMBER"),
39	  },
40	  required: ["transcript"],
41	};
42	
43	const PROVINCES = ["AB", "BC", "MB", "NB", "NL", "NS", "NT", "NU", "ON", "PE", "QC", "SK", "YT"];
44	// Sanity ranges. Anything outside is rejected (set to null) and reported, never passed on.
45	const RANGES = {
46	  age: [13, 100],
47	  income_per_year: [0, 5_000_000],
48	  tfsa: [0, 50_000_000],
49	  rrsp: [0, 50_000_000],
50	  other_savings: [0, 50_000_000],
51	  saving_per_month: [0, 100_000],
52	  retirement_age: [40, 80],
53	  exercise_per_week: [0, 21],
54	  sleep_hours: [2, 14],
55	  drinks_per_week: [0, 100],
56	};
57	
58	// Raw model output -> contract-shaped fields (nulls kept) + a list of values we refused.
59	export function normalize(raw = {}) {
60	  const rejected = [];
61	  const num = (key) => {
62	    const v = raw[key];
63	    if (v === null || v === undefined) return null;
64	    const [lo, hi] = RANGES[key];
65	    if (typeof v !== "number" || !Number.isFinite(v) || v < lo || v > hi) {
66	      rejected.push(key);
67	      return null;
68	    }
69	    return v;
70	  };
71	  const age = num("age");
72	  const retirement_age = num("retirement_age");
73	  let province = typeof raw.province === "string" ? raw.province.trim().toUpperCase() : null;
74	  if (province && !PROVINCES.includes(province)) (rejected.push("province"), (province = null));
75	  const sex = raw.sex === "male" || raw.sex === "female" ? raw.sex : null;
76	  const name = typeof raw.name === "string" && raw.name.trim() ? raw.name.trim().replace(/[{}]/g, "").slice(0, 40) : null;
77	  const smoker = typeof raw.smoker === "boolean" ? raw.smoker : null;
78	  if (age !== null && retirement_age !== null && retirement_age <= age) rejected.push("retirement_age");
79	
80	  return {
81	    rejected,
82	    fields: {
83	      name,
84	      age,
85	      sex,
86	      province,
87	      income_per_year: num("income_per_year"),
88	      savings: { tfsa: num("tfsa"), rrsp: num("rrsp"), other: num("other_savings") },
89	      saving_per_month: num("saving_per_month"),
90	      retirement_age: age !== null && retirement_age !== null && retirement_age <= age ? null : retirement_age,
91	      habits: {
92	        exercise_per_week: num("exercise_per_week"),
93	        sleep_hours: num("sleep_hours"),
94	        smoker,
95	        drinks_per_week: num("drinks_per_week"),
96	      },
97	    },
98	  };
99	}
100	
101	// PLAN.md Part 1 defaults. Where the plan's default is "typical for your age/sex/habits"
102	// (income, sex, habits) we leave null: the simulation supplies those from its own data.
103	const DEFAULTS = { age: 20, province: "ON", saving_per_month: 0, retirement_age: 65, savings: { tfsa: 0, rrsp: 0, other: 0 } };
104	
105	export function withDefaults(fields) {
106	  const assumed = [];
107	  const pick = (path, value, fallback) => {
108	    if (value === null || value === undefined) {
109	      assumed.push(path);
110	      return fallback;
111	    }
112	    return value;
113	  };
114	  const profile = {
115	    name: pick("name", fields.name, null),
