137	// Ask Gemini. Give it either { transcript } or { audio: Buffer, mime }.
138	export async function extractFields({
139	  transcript,
140	  audio,
141	  mime = "audio/webm",
142	  apiKey = process.env.GEMINI_API_KEY,
143	  model = process.env.GEMINI_MODEL || DEFAULT_MODEL,
144	  fetchFn = fetch,
145	}) {
146	  if (!apiKey) throw new Error("interview reading is off: set GEMINI_API_KEY");
147	  if (!transcript && !audio) throw new Error("nothing to read: send a transcript or a recording");
148	
149	  const parts = audio
150	    ? [{ text: "Here is the interview recording. Fill in the form." }, { inline_data: { mime_type: mime.split(";")[0], data: Buffer.from(audio).toString("base64") } }]
151	    : [{ text: `Here is the interview transcript:\n\n${transcript}\n\nFill in the form.` }];
152	
153	  const res = await fetchFn(`${API}/${model}:generateContent`, {
154	    method: "POST",
155	    headers: { "x-goog-api-key": apiKey, "content-type": "application/json" },
156	    body: JSON.stringify({
157	      systemInstruction: { parts: [{ text: SYSTEM }] },
158	      contents: [{ role: "user", parts }],
159	      generationConfig: { responseMimeType: "application/json", responseSchema: SCHEMA, temperature: 0 },
160	    }),
161	  });
162	  if (!res.ok) throw new Error(`Gemini ${res.status}: ${(await res.text()).slice(0, 300)}`);
163	  const body = await res.json();
164	  const text = body?.candidates?.[0]?.content?.parts?.map((p) => p.text ?? "").join("");
165	  let raw;
166	  try {
167	    raw = JSON.parse(text);
168	  } catch {
169	    throw new Error("Gemini did not return readable fields");
170	  }
171	  const { fields, rejected } = normalize(raw);
172	  const { profile, assumed } = withDefaults(fields);
173	  return { transcript: transcript ?? String(raw.transcript ?? ""), heard: fields, profile, assumed, rejected };
174	}
